import { signUpNewAccount, type SignUpRequest, type SignUpResponse } from '~/client';
import { showToastError } from '~/utils/show-toast';

export const useSignUp = defineMutation(() => {
  const { mutate: signUp, asyncStatus } = useMutation({
    mutation: async (signUpForm: SignUpRequest) =>
      (await signUpNewAccount({
        composable: '$fetch',
        body: ref({
          ...signUpForm,
          phone: signUpForm.phone.replaceAll('-', '').replaceAll(' ', ''),
          referral_code: signUpForm.referral_code ?? undefined,
        }),
      })) as SignUpResponse,
    onSuccess: async (newData: SignUpResponse) => {
      await navigateTo({ name: 'sign-up-email-confirmation-user_id', params: { user_id: newData.user_id } });
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    signUp,
    isSigningUp: computed(() => asyncStatus.value === 'loading'),
  };
});
