import * as z from 'zod';
import { passwordRegex, phoneNumberRegex, userNameRegex } from '~/constants/regularExpressions';

export const signUpFormSchema = z
  .object({
    first_name: z
      .string({ message: 'First Name is required' })
      .trim()
      .min(1, { message: 'First Name is required' })
      .max(255, { message: 'First name cannot exceed 255 characters' })
      .regex(userNameRegex, {
        message: 'Name can only contain letters, numbers, spaces, hyphens, apostrophes, and periods',
      }),

    last_name: z
      .string({ message: 'Last Name is required' })
      .trim()
      .min(1, { message: 'Last Name is required' })
      .max(255, { message: 'Last name cannot exceed 255 characters' })
      .regex(userNameRegex, {
        message: 'Name can only contain letters, numbers, spaces, hyphens, apostrophes, and periods',
      }),

    email: z
      .string({ message: 'Email is required' })
      .trim()
      .nonempty({ message: 'Email is required' })
      .email({ message: 'Please enter a valid email address' })
      .toLowerCase(),

    phone: z
      .string({ message: 'Phone number is required' })
      .trim()
      .nonempty({ message: 'Phone number is required' })
      .regex(phoneNumberRegex, { message: 'Phone must follow format: +1 XXX-XXX-XXXX' }),

    password: z.string({ message: 'Password is required' }).regex(passwordRegex, {
      message:
        'Password must contain at least 8 characters, with upper and lowercase letters, a number, a special symbol, and no spaces',
    }),
    confirm_password: z
      .string({ message: 'Confirmation password is required' })
      .trim()
      .nonempty({ message: 'Confirmation password is required' }),

    agreed_to_terms: z
      .boolean()
      .default(false)
      .refine((val) => val === true, {
        message: 'You must agree to the Terms & Conditions',
      }),

    sms_consent: z.boolean().default(false),
  })
  .refine((data) => data.password === data.confirm_password, {
    message: 'Passwords must match',
    path: ['confirm_password'],
  });
